{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.return_fact_items AS WITH sales_data_pre AS ( SELECT sku_group, order_name, line_item_id, sku, customer_name, phone, order_timestamp::date AS order_date, CASE when lower(tags) like \'%snitch_web%\' then \'Web\' WHEN webshopney IN (\'Shopney\', \'Appbrew\') THEN \'Appbrew\' WHEN webshopney = \'Snitch_IOS\' AND tags LIKE \'%Snitch_IOS%\' THEN \'IOS\' WHEN webshopney = \'Snitch_IOS\' AND tags LIKE \'%Snitch_Android%\' THEN \'Android\' ELSE \'Web\' END AS channel, case when LOWER(IFNULL(discount_code, \'n\')) LIKE \'%eco%\' then 1 when LOWER(IFNULL(discount_code, \'n\')) LIKE \'%influ%\' then 1 when order_name IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') then 1 when tags IN (\'FLITS_LOGICERP\') then 1 when lower(tags) like \'%creator%\' then 1 else 0 end as filters, state, pincode, quantity AS sales_qty, gross_sales AS sales_value FROM snitch_db.maplemonk.fact_items_snitch WHERE order_timestamp::date > \'2023-10-01\' ), sales_data as ( select * from sales_data_pre where filters = 0 ), prod as ( select sku_group, final_live_date as live_date, category, CASE WHEN category IN (\'Joggers & Trackpants\', \'Cargo Pants\', \'Boxers\', \'Jeans\', \'Night Suit & Pyjamas\', \'Trousers\', \'Chinos\', \'Shorts\') THEN \'bottom_wear\' WHEN category IN (\'Shirt\', \'Overshirt\', \'Hoodies\', \'Sweaters\', \'T-Shirts\', \'Sweatshirts\', \'Shirts\', \'Jackets\', \'Blazers\') THEN \'top_wear\' WHEN category IN (\'Accessories\', \'Sunglasses\', \'Shoes\', \'Inner Wear\', \'Perfumes\') THEN \'accessories\' ELSE \'others\' END AS top_bottom from snitch_db.maplemonk.base_product qualify row_number() over (partition by sku_group order by status desc) = 1 ), final_sales_table AS ( SELECT a.*, b.live_date, b.category, b.top_bottom FROM sales_data a LEFT JOIN prod b ON a.sku_group = b.sku_group ), sku_group_fit AS ( SELECT sku_group, fit from snitch_db.maplemonk.metafields_data qualify row_number() over (partition by sku_group order by status desc) = 1 ), returns_rms as ( SELECT replace(shopify_order_number,\',\',\'\') as order_id, sku, case when reason in (\'I changed my mind\',\'i change my mind\',\'I change my mind\') then \'mind_change\' when reason in (\'Product looks different from website\',\'product looks different from website\') then \'product_different_from_website\' when reason in (\'Size or fit issue\',\'size or fit issue\') then \'size\' when reason in (\'product quality issue\',\'Product quality issue\') then \'quality\' when reason in (\'wrong or defective product\',\'Wrong or defective product\') then \'wpr\' else \'others\' end as reason, sub_reason as return_reason, return_quantity as return_qty FROM SNITCH_DB.MAPLEMONK.RMS20251215 ), returns_rms_post as ( SELECT replace(shopify_order_number,\',\',\'\') as order_id, sku, case when reason in (\'I changed my mind\',\'i change my mind\',\'I change my mind\') then \'mind_change\' when reason in (\'Product looks different from website\',\'product looks different from website\') then \'product_different_from_website\' when reason in (\'Size or fit issue\',\'size or fit issue\') then \'size\' when reason in (\'product quality issue\',\'Product quality issue\') then \'quality\' when reason in (\'wrong or defective product\',\'Wrong or defective product\') then \'wpr\' else \'others\' end as reason, sub_reason as return_reason, return_quantity as return_qty FROM SNITCH_DB.MAPLEMONK.rms_upload_before_july26 union SELECT replace(shopify_order_number,\',\',\'\') as order_id, sku, case when reason in (\'I changed my mind\',\'i change my mind\',\'I change my mind\') then \'mind_change\' when reason in (\'Product looks different from website\',\'product looks different from website\') then \'product_different_from_website\' when reason in (\'Size or fit issue\',\'size or fit issue\') then \'size\' when reason in (\'product quality issue\',\'Product quality issue\') then \'quality\' when reason in (\'wrong or defective product\',\'Wrong or defective product\') then \'wpr\' else \'others\' end as reason, sub_reason as return_reason, return_quantity as return_qty FROM SNITCH_DB.MAPLEMONK.rms_20260824 ), return_before_19 AS ( SELECT sku, LEFT(sku, LENGTH(sku) - CHARINDEX(\'-\', REVERSE(sku))) AS sku_group, order_id, quantity AS return_qty, sub_reason_detail as return_reason, CASE WHEN LOWER(return_reasons) = \'product looks different from website\' THEN \'product_different_from_website\' WHEN LOWER(return_reasons) IN (\'i do not like the product\', \'product quality issue\') THEN \'quality\' WHEN LOWER(return_reasons) IN (\'size is too large\', \'size is too small\', \'size or fit issue\') THEN \'size\' WHEN LOWER(return_reasons) IN (\'wrong item shipped\', \'i received a defective item\', \'wrong item received\', \'wrong size shipped\', \'wrong or defective product\') THEN \'wpr\' WHEN LOWER(return_reasons) = \'delivery was delayed\' THEN \'delivery_delayed\' WHEN LOWER(return_reasons) = \'i change my mind\' THEN \'mind_change\' END AS reason FROM snitch_db.maplemonk.ecoreturns_final_returns WHERE status != \'REJECTED\' AND REQUEST_TYPE IN (\'Return\') ), main_data AS ( SELECT a.*, IFNULL(b.return_qty, 0) AS return_qty, COALESCE(b.return_reason, \'not_returned\') AS return_reasons, COALESCE(b.reason, \'not_returned\') AS reason, c.live_date, c.category AS category, c.top_bottom, e.fit FROM sales_data a LEFT JOIN returns_rms b ON a.sku = b.sku AND CAST(a.order_name AS VARCHAR) = CAST(b.order_id AS VARCHAR) LEFT JOIN prod c ON a.sku_group = c.sku_group LEFT JOIN sku_group_fit e ON a.sku_group = e.sku_group WHERE a.order_date >= \'2024-11-20\' and a.order_date < \'2025-11-01\' UNION SELECT a.*, IFNULL(b.return_qty, 0) AS return_qty, COALESCE(b.return_reason, \'not_returned\') AS return_reasons, COALESCE(b.reason, \'not_returned\') AS reason, c.live_date, c.category AS category, c.top_bottom, e.fit FROM sales_data a LEFT JOIN returns_rms_post b ON a.sku = b.sku AND CAST(a.order_name AS VARCHAR) = CAST(b.order_id AS VARCHAR) LEFT JOIN prod c ON a.sku_group = c.sku_group LEFT JOIN sku_group_fit e ON a.sku_group = e.sku_group WHERE a.order_date >= \'2025-11-01\' union SELECT a.*, IFNULL(b.return_qty, 0) AS return_qty, COALESCE(b.return_reason, \'not_returned\') AS return_reasons, COALESCE(b.reason, \'not_returned\') AS reason, c.live_date, c.category AS category, c.top_bottom, e.fit FROM sales_data a LEFT JOIN return_before_19 b ON a.sku = b.sku AND a.sku_group = b.sku_group AND CAST(a.order_name AS VARCHAR) = CAST(b.order_id AS VARCHAR) LEFT JOIN prod c ON a.sku_group = c.sku_group LEFT JOIN sku_group_fit e ON a.sku_group = e.sku_group WHERE a.order_date < \'2024-11-20\' ), exchange AS ( SELECT order_name, sku_group, line_item_sales, gross_sales, tags, REGEXP_SUBSTR(tags, \'Snitch-RMS-Exchange for ([0-9]+)\', 1, 1, \'e\', 1) AS original_line_item_id FROM snitch_db.maplemonk.fact_items_snitch WHERE POSITION(\'Snitch-RMS-Exchange for\' IN tags) > 0 ), main_data2 AS ( SELECT sku_group, order_name, sku, line_item_id, customer_name, phone, order_date, channel, state, pincode, sales_qty, sales_value, return_qty, CASE WHEN TRIM(line_item_id) IN (SELECT DISTINCT TRIM(original_line_item_id) FROM exchange) THEN 0 ELSE return_qty END AS return_qty_real, return_reasons, reason, live_date, category, top_bottom, fit FROM main_data ) SELECT *, CASE WHEN return_qty != 0 THEN (sales_value / sales_qty) * return_qty_real ELSE 0 END AS return_value FROM main_data2; create or replace table snitch_db.maplemonk.noreturns_returns as with nor as ( select order_name, case when discount_code in (\'NORETURN10\', \'NORETURN5\') then \'no-return\' else \'others\' end as no_return from snitch_db.maplemonk.fact_items_snitch qualify row_number() over ( partition by order_name order by discount_code desc ) = 1 ) select a.order_date, case when a.pincode in ( \'335804\',\'509125\',\'390007\',\'303301\',\'342008\',\'303313\',\'302015\', \'342005\',\'302019\',\'342001\',\'533104\',\'342007\',\'110011\',\'342003\', \'700118\',\'342601\',\'302033\',\'303120\',\'303905\',\'303119\',\'332706\', \'342605\',\'342015\',\'303121\',\'342014\',\'122108\',\'302017\',\'303109\', \'302029\',\'515801\',\'342026\',\'303104\',\'303801\',\'342304\',\'303103\', \'304024\',\'342027\',\'802212\',\'342006\',\'413224\',\'342013\',\'342801\', \'303002\',\'332701\',\'302022\',\'303004\',\'302028\',\'122508\',\'342012\', \'321303\',\'302038\',\'332028\',\'303001\',\'303507\' ) then \'fraud\' else \'non-fraud\' end as fraud_filter, coalesce(b.no_return, \'others\') as no_return, sum(a.sales_value) as sales_value, sum(a.return_value) as return_value from snitch_db.maplemonk.return_fact_items a left join nor b on a.order_name = b.order_name group by 1, 2, 3 order by 1, 2;",
